1980		}
1981		source := manifest.Sources.Semantic
1982		if source.SnapshotPath == "" {
1983			axes["snapshot"] = staleAxis{State: "unsafe", Detail: "semantic snapshot_path is missing"}
1984		} else if _, err := validateSemanticSnapshotPath(source.SnapshotPath); err != nil {
1985			axes["snapshot"] = staleAxis{State: "unsafe", Detail: err.Error()}
1986		} else if err := rejectSymlinkPathComponents(storage.BrainDir, filepath.FromSlash(source.SnapshotPath)); err != nil {
1987			axes["snapshot"] = staleAxis{State: "unsafe", Detail: err.Error()}
1988		} else {
1989			snapshotPath := filepath.Join(storage.BrainDir, filepath.FromSlash(source.SnapshotPath))
