1991			if snapshotErr != nil {
1992				axes["snapshot"] = staleAxis{State: "unsafe", Detail: snapshotErr.Error()}
1993			} else if err := validateSemanticSourceMatchesSnapshot(source, snapshotHeader, snapshotCounts); err != nil {
1994				axes["snapshot"] = staleAxis{State: "unsafe", Detail: err.Error()}
1995			} else {
1996				axes["snapshot"] = staleAxis{State: "ok", Detail: source.SnapshotPath}
1997			}
1998		}
1999		if source.StorePath != "" {
2000			if source.GenerationPath == "" {
2001				axes["store"] = staleAxis{State: "unsafe", Detail: "semantic generation_path is missing"}
2002			} else if generationPath, err := validateSemanticGenerationPath(source.GenerationPath); err != nil {
2003				axes["store"] = staleAxis{State: "unsafe", Detail: err.Error()}
2004			} else if storePath, err := validateSemanticGenerationFilePath(source.StorePath, generationPath, semanticSQLiteName); err != nil {
2005				axes["store"] = staleAxis{State: "unsafe", Detail: err.Error()}
2006			} else if err := rejectSymlinkPathComponents(storage.BrainDir, storePath); err != nil {
2007				axes["store"] = staleAxis{State: "unsafe", Detail: err.Error()}
2008			} else if err := validateSemanticSQLiteStore(filepath.Join(storage.BrainDir, storePath), source.Symbols, source.Relations); err != nil {
2009				axes["store"] = staleAxis{State: "unsafe", Detail: err.Error()}
2010			} else {
2011				axes["store"] = staleAxis{State: "ok", Detail: source.StorePath}
2012			}
2013		}
2014		head, headErr := gitScalar(ctx, opts.Runner, repoDir, "rev-parse", "HEAD")
2015		branch, branchErr := gitScalar(ctx, opts.Runner, repoDir, "branch", "--show-current")
2016		dirty, dirtyErr := worktreeDirty(ctx, opts.Runner, repoDir)
2017		currentWorktreeHash := ""
2018		var currentWorktreeHashErr error
2019		if dirty && source.WorktreeHash != "" {
2020			currentWorktreeHash, currentWorktreeHashErr = worktreeFingerprint(ctx, opts.Runner, repoDir)
2021		}
2022		if headErr != nil {
2023			axes["head"] = staleAxis{State: "unsafe", Detail: "HEAD unavailable: " + headErr.Error(), Indexed: source.Commit}
2024		} else if source.Commit == head {
2025			axes["head"] = staleAxis{State: "ok", Current: head, Indexed: source.Commit}
2026		} else {
2027			axes["head"] = staleAxis{State: "stale", Current: head, Indexed: source.Commit}
2028		}
2029		if branchErr != nil {
2030			axes["branch_tip"] = staleAxis{State: "unsafe", Detail: "branch unavailable: " + branchErr.Error(), Indexed: source.Branch}
2031		} else if source.Branch == "" || source.Branch == branch {
2032			axes["branch_tip"] = staleAxis{State: "ok", Current: branch, Indexed: source.Branch}
2033		} else {
2034			axes["branch_tip"] = staleAxis{State: "stale", Current: branch, Indexed: source.Branch}
2035		}
2036		switch {
