2038			axes["worktree"] = staleAxis{State: "unsafe", Detail: "worktree status unavailable: " + dirtyErr.Error()}
2039		case dirty && source.WorktreeMode != "worktree":
2040			axes["worktree"] = staleAxis{State: "dirty-unindexed", Detail: "semantic index is based on committed HEAD"}
2041		case currentWorktreeHashErr != nil:
2042			axes["worktree"] = staleAxis{State: "unsafe", Detail: "worktree fingerprint unavailable: " + currentWorktreeHashErr.Error()}
2043		case dirty && source.WorktreeHash != "" && source.WorktreeHash != currentWorktreeHash:
2044			axes["worktree"] = staleAxis{State: "dirty-stale", Detail: "dirty worktree changed since semantic indexing"}
2045		case dirty:
2046			axes["worktree"] = staleAxis{State: "dirty-indexed"}
2047		case source.WorktreeMode == "worktree":
2048			axes["worktree"] = staleAxis{State: "worktree-overlay-stale", Detail: "active semantic index was built from dirty content but worktree is now clean"}
2049		default:
2050			axes["worktree"] = staleAxis{State: "clean"}
2051		}
2052		if source.Provider == "skipped" || semanticWarningsContainCode(source.Warnings, "provider_skipped") {
2053			axes["provider"] = staleAxis{State: "degraded", Detail: "semantic provider was skipped"}
2054		} else if err := validateSemanticSchema(source.SchemaVersion); err != nil {
2055			axes["provider"] = staleAxis{State: "unsafe", Detail: err.Error()}
2056		} else if !source.NoEgressVerified {
2057			axes["provider"] = staleAxis{State: "degraded", Detail: "provider no-egress status was not verified"}
2058		} else {
2059			axes["provider"] = staleAxis{State: "ok", Detail: source.Provider + " " + source.ProviderVersion}
2060		}
2061		if source.Provider == "skipped" || semanticWarningsContainCode(source.Warnings, "provider_skipped") {
2062			axes["semantic_completeness"] = staleAxis{State: "unsafe", Detail: "semantic facts unavailable"}
2063		} else if len(source.PartialFailures) > 0 {
2064			axes["semantic_completeness"] = semanticCompletenessAxis(source)
2065		} else {
2066			axes["semantic_completeness"] = staleAxis{State: "ok"}
2067		}
2068		severity := aggregateStaleSeverity(axes)
2069		return staleReport{Severity: severity, Axes: axes, Warnings: source.Warnings}, nil
2070	}
