2072	func semanticWarningsContainCode(warnings []semanticWarning, code string) bool {
2073		for _, warning := range warnings {
2074			if warning.Code == code {
2075				return true
2076			}
2077		}
2078		return false
2079	}
2080	
2081	// semanticParseErrorCode marks files where the tree-sitter parse produced error
2082	// nodes but symbols were still extracted (error-tolerant parse). A small number
2083	// of these is expected for any real codebase — newer language syntax the bundled
2084	// grammar version predates — and does not make the indexed facts unsafe to use.
2085	const semanticParseErrorCode = "E_PARSE_ERROR"
2086	
2087	// semanticParseErrorTolerance is the fraction of indexed files that may carry
2088	// only benign parse errors before the brain is reported as degraded. Below this
2089	// threshold the completeness axis stays ok; the failures remain recorded in the
2090	// semantic source so they can still be inspected and acted on. Above it, the
2091	// volume is high enough to suspect a grammar/provider problem worth surfacing.
2092	const semanticParseErrorTolerance = 0.10
2093	
2094	// semanticCompletenessAxis classifies partial provider failures. Failures that
2095	// are exclusively benign parse errors and stay under the tolerance fraction keep
2096	// the axis ok; anything else (a non-parse failure code, an uncountable file set,
2097	// or too many parse errors) degrades the brain.
2098	func semanticCompletenessAxis(source *semanticSourceManifest) staleAxis {
2099		failures := len(source.PartialFailures)
2100		parseErrors := 0
2101		for _, failure := range source.PartialFailures {
2102			if failure.Code == semanticParseErrorCode {
2103				parseErrors++
2104			}
2105		}
2106		if parseErrors == failures && source.Files > 0 {
2107			fraction := float64(failures) / float64(source.Files)
2108			if fraction < semanticParseErrorTolerance {
2109				return staleAxis{State: "ok", Detail: fmt.Sprintf("%d/%d files had tolerated parse errors", failures, source.Files)}
2110			}
2111			return staleAxis{State: "degraded", Detail: fmt.Sprintf("%d partial failures in %.0f%% of files", failures, fraction*100)}
2112		}
2113		return staleAxis{State: "degraded", Detail: strconv.Itoa(failures) + " partial failures"}
2114	}
