2116	func aggregateStaleSeverity(axes map[string]staleAxis) string {
2117		severity := "ok"
2118		for _, axis := range axes {
2119			switch axis.State {
2120			case "missing", "unsafe", "stale", "dirty-stale", "worktree-overlay-stale":
2121				return "unsafe"
2122			case "degraded", "dirty-unindexed":
2123				severity = "degraded"
2124			}

