func main() {
	src, _ := os.ReadFile(os.Args[1])
	root, _ := sitter.ParseCtx(context.Background(), src, sql.GetLanguage())
	fmt.Println("has_error:", root.HasError())
	// find first ERROR or MISSING node
	var walk func(n *sitter.Node)
	count := 0
	walk = func(n *sitter.Node) {
		if n == nil {
			return
		}
		if (n.IsError() || n.IsMissing()) && count < 8 {
			s := n.StartPoint()
			e := n.EndPoint()
			snippet := string(src[n.StartByte():min(n.EndByte(), n.StartByte()+80)])
			fmt.Printf("  [%s] line %d:%d-%d:%d  type=%s  src=%q\n",
				map[bool]string{true: "ERROR", false: "MISSING"}[n.IsError()],
				s.Row+1, s.Column, e.Row+1, e.Column, n.Type(), snippet)
			count++
		}
		for i := 0; i < int(n.ChildCount()); i++ {
			walk(n.Child(i))
		}
	}
	walk(root)
	fmt.Println("error/missing nodes shown:", count)
}
